import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));

        int n = Integer.parseInt(br.readLine().trim());

        if (n <= 0) {
            System.out.println(-1);
            return;
        }

        String[] tokens = br.readLine().trim().split("\\s+");
        int[] arr = new int[n];
        for (int i = 0; i < n; i++) {
            arr[i] = Integer.parseInt(tokens[i]);
        }

        int k = Integer.parseInt(br.readLine().trim());

        Set<String> seen = new HashSet<>();
        List<String> pairs = new ArrayList<>();

        for (int i = 0; i < n; i++) {
            int complement = k - arr[i];
            String key = Math.min(arr[i], complement) + "," + Math.max(arr[i], complement);

            if (seen.contains(key)) {
                continue;
            }

            for (int j = i + 1; j < n; j++) {
                if (arr[j] == complement) {
                    pairs.add(key);
                    seen.add(key);
                    break;
                }
            }
        }

        if (pairs.isEmpty()) {
            System.out.println(-1);
        } else {
            Collections.sort(pairs, (a, b) -> {
                int[] pa = a.split(",").length == 2 ? 
                    new int[]{Integer.parseInt(a.split(",")[0]), Integer.parseInt(a.split(",")[1])} : new int[]{0, 0};
                int[] pb = b.split(",").length == 2 ? 
                    new int[]{Integer.parseInt(b.split(",")[0]), Integer.parseInt(b.split(",")[1])} : new int[]{0, 0};
                if (pa[0] != pb[0]) return pa[0] - pb[0];
                return pa[1] - pb[1];
            });

            for (String pair : pairs) {
                String[] parts = pair.split(",");
                System.out.println("(" + parts[0] + "," + parts[1] + ")");
            }
        }
    }
}
